import * as THREE from './vendor/three.module.js';
import {ORDER,INFO,stickerPose,TURNS} from './engine.mjs';
export class CubeView{
 constructor(container){this.container=container;this.scene=new THREE.Scene();this.camera=new THREE.PerspectiveCamera(34,1,.1,100);this.renderer=new THREE.WebGLRenderer({antialias:true,alpha:true});this.renderer.setPixelRatio(Math.min(devicePixelRatio,2));this.renderer.setClearColor(0x000000,0);container.append(this.renderer.domElement);this.renderer.domElement.setAttribute('aria-label','Interactive 3D cube. Drag to inspect its sides.');this.renderer.domElement.setAttribute('role','img');this.root=new THREE.Group();this.scene.add(this.root);this.yaw=.62;this.pitch=.46;this.scene.add(new THREE.AmbientLight(0xffffff,2));const light=new THREE.DirectionalLight(0xffffff,2.8);light.position.set(-3,7,8);this.scene.add(light);this.geometry=new THREE.BoxGeometry(.98,.98,.98);this.stickerGeometry=new THREE.BoxGeometry(.84,.84,.015);this.dark=new THREE.MeshStandardMaterial({color:0x15231f,roughness:.6});this.materials=Object.fromEntries([...ORDER,'?'].map(k=>[k,new THREE.MeshStandardMaterial({color:k==='?'?0x416359:INFO[k].hex,roughness:.55})]));this.observer=new ResizeObserver(()=>this.resize());this.observer.observe(container);this.drag=null;let el=this.renderer.domElement;el.style.touchAction='none';el.addEventListener('pointerdown',e=>{this.drag={x:e.clientX,y:e.clientY};el.setPointerCapture(e.pointerId);});el.addEventListener('pointermove',e=>{if(!this.drag)return;this.yaw-=(e.clientX-this.drag.x)*.009;this.pitch=Math.max(-1.2,Math.min(1.2,this.pitch+(e.clientY-this.drag.y)*.008));this.drag={x:e.clientX,y:e.clientY};this.render();});for(let evt of ['pointerup','pointercancel'])el.addEventListener(evt,()=>this.drag=null);this.resize();}
 resize(){const w=this.container.clientWidth,h=this.container.clientHeight;this.renderer.setSize(w,h);this.camera.aspect=w/h;this.camera.updateProjectionMatrix();this.render();}
 render(){const d=10.9;this.camera.position.set(Math.sin(this.yaw)*Math.cos(this.pitch)*d,Math.sin(this.pitch)*d,Math.cos(this.yaw)*Math.cos(this.pitch)*d);this.camera.lookAt(0,0,0);this.renderer.render(this.scene,this.camera);}
 reset(){this.yaw=.62;this.pitch=.46;this.render();}
 focus(face){const views={F:[0,0],B:[Math.PI,0],R:[Math.PI/2,0],L:[-Math.PI/2,0],U:[0,1.2],D:[0,-1.2]};[this.yaw,this.pitch]=views[face];this.render();}
 setState(faces){this.root.clear();this.cubies=[];let map={};for(let x=-1;x<=1;x++)for(let y=-1;y<=1;y++)for(let z=-1;z<=1;z++){if(!x&&!y&&!z)continue;let cubie=new THREE.Group();cubie.position.set(x,y,z);cubie.add(new THREE.Mesh(this.geometry,this.dark));map[[x,y,z].join(',')]=cubie;this.root.add(cubie);this.cubies.push(cubie);}for(let f of ORDER)for(let i=0;i<9;i++){const {pos,normal}=stickerPose(f,Math.floor(i/3),i%3);let sticker=new THREE.Mesh(this.stickerGeometry,this.materials[faces[f][i]]||this.materials['?']);sticker.position.fromArray(normal).multiplyScalar(.499);sticker.quaternion.setFromUnitVectors(new THREE.Vector3(0,0,1),new THREE.Vector3(...normal));map[pos.join(',')].add(sticker);}this.render();}
 async turn(move,after,duration=600){const {axis,sign}=TURNS[move[0]],group=new THREE.Group();this.root.add(group);for(let cubie of this.cubies)if(Math.round(cubie.position[axis])===sign)group.attach(cubie);const target=-sign*Math.PI/2*(move.endsWith('2')?2:move.endsWith("'")?-1:1),start=performance.now();if(matchMedia('(prefers-reduced-motion: reduce)').matches)duration=0;await new Promise(resolve=>{const step=t=>{let k=duration?Math.min(1,(t-start)/duration):1;group.rotation[axis]=target*(k<.5?2*k*k:1-(-2*k+2)**2/2);this.render();if(k<1)requestAnimationFrame(step);else resolve();};requestAnimationFrame(step);});this.setState(after);}
}
